    def stripe_lines(vectors, limit):
        lines = []
        for i, vec in enumerate(vectors):
            counts = {}
            for x in vec:
                if x != 0:
                    counts[x] = counts.get(x, 0) + 1
            if counts and max(counts.values()) >= limit - 2:
                lines.append(i)
        return lines

    row_lines = stripe_lines(grid, w)
    col_lines = stripe_lines(
        [[grid[r][c] for r in range(h)] for c in range(w)], h
    )

    def keep_indices(length, lines):
        kept = []
        start = 0
        for line in lines:
            if start < line:
                kept.append(start)
            kept.append(line)
            start = line + 1
        if start < length:
            kept.append(start)
        return kept

    rows = keep_indices(h, row_lines)
    cols = keep_indices(w, col_lines)
    return [[grid[r][c] for c in cols] for r in rows]
